export function assertCryptoKey(t){if(!isCryptoKey(t))throw new Error("CryptoKey instance expected")}export const isCryptoKey=t=>{if("CryptoKey"===t?.[Symbol.toStringTag])return!0;try{return t instanceof CryptoKey}catch{return!1}};export const isKeyObject=t=>"KeyObject"===t?.[Symbol.toStringTag];export const isKeyLike=t=>isCryptoKey(t)||isKeyObject(t);